248	template <typename FpType>
249	inline bool TryEstimateSupportedCycles(PtoOpcode op, uint64_t rows, uint64_t cols, uint64_t& cycles)
250	{
251	    switch (op) {
252	        case PtoOpcode::TSUB:
253	            return fit::TryEstimateFormulaCycles<FpType>("TSUB", rows, cols, cycles);
254	        case PtoOpcode::TMUL:
255	            return fit::TryEstimateFormulaCycles<FpType>("TMUL", rows, cols, cycles);
256	        case PtoOpcode::TADDS:
257	            return fit::TryEstimateFormulaCycles<FpType>("TADDS", rows, cols, cycles);
258	        case PtoOpcode::TDIVS:
259	            return fit::TryEstimateFormulaCycles<FpType>("TDIVS", rows, cols, cycles);
260	        case PtoOpcode::TMULS:
261	            return fit::TryEstimateFormulaCycles<FpType>("TMULS", rows, cols, cycles);
262	        case PtoOpcode::TMINS:
263	            return fit::TryEstimateFormulaCycles<FpType>("TMINS", rows, cols, cycles);
264	        case PtoOpcode::TROWSUM:
265	            return fit::TryEstimateFormulaCycles<FpType>("TROWSUM", rows, cols, cycles);
266	        case PtoOpcode::TROWMAX:
267	            return fit::TryEstimateFormulaCycles<FpType>("TROWMAX", rows, cols, cycles);
268	        case PtoOpcode::TCOLSUM:
269	            return fit::TryEstimateFormulaCycles<FpType>("TCOLSUM", rows, cols, cycles);
270	        case PtoOpcode::TCOLMAX:
271	            return fit::TryEstimateFormulaCycles<FpType>("TCOLMAX", rows, cols, cycles);
272	        case PtoOpcode::TROWEXPAND:
273	            return fit::TryEstimateFormulaCycles<FpType>("TROWEXPAND", rows, cols, cycles);
274	        case PtoOpcode::TEXP:
275	            return fit::TryEstimateFormulaCyclesAnyDType<FpType>("TEXP", rows, cols, cycles);
276	        case PtoOpcode::TSQRT:
277	            return fit::TryEstimateFormulaCyclesAnyDType<FpType>("TSQRT", rows, cols, cycles);
278	        default:
279	            return false;
280	    }
281	}
