283	inline bool TryEstimateMatmulCycles(const CostModelInput& input, uint64_t& cycles)
284	{
285	    if (input.rows <= 0 || input.k <= 0 || input.cols <= 0) {
286	        return false;
287	    }
288	    const uint64_t m = static_cast<uint64_t>(input.rows);
289	    const uint64_t k = static_cast<uint64_t>(input.k);
290	    const uint64_t n = static_cast<uint64_t>(input.cols);
291	
292	    switch (input.dtype) {
293	        case DType::Float:
294	            return fit::TryEstimateMadCycles<float, float, float>(m, k, n, cycles);
295	        case DType::Half:
296	            return fit::TryEstimateMadCycles<half, half, half>(m, k, n, cycles);
297	        default:
298	            return false;
299	    }
300	}
301	
302	inline bool TryGetDTypeSizeBytes(DType dtype, uint64_t& bytes)
303	{
304	    constexpr uint64_t kByteOne = 1;
305	    constexpr uint64_t kByteTwo = 2;
306	    constexpr uint64_t kByteFour = 4;
307	    switch (dtype) {
308	        case DType::Int8:
309	        case DType::Uint8:
310	            bytes = kByteOne;
311	            return true;
312	        case DType::Half:
313	        case DType::Int16:
314	        case DType::Uint16:
315	        case DType::BFloat16:
316	            bytes = kByteTwo;
317	            return true;
318	        case DType::Float:
319	        case DType::Int32:
320	        case DType::Uint32:
321	            bytes = kByteFour;
322	            return true;
323	        default:
324	            return false;
325	    }
326	}
327	
328	inline bool TryEstimateTransferLatency(
329	    const CostModelInput& input, const PredictRuntimeConfig& predict_config, CostModelResult& result)
330	{
331	    if (input.data_size <= 0) {
332	        return false;
333	    }
334	    uint64_t dtype_bytes = 0;
335	    if (!TryGetDTypeSizeBytes(input.dtype, dtype_bytes)) {
336	        return false;
337	    }
338	    const uint64_t elements = static_cast<uint64_t>(input.data_size);
339	    const uint64_t bytes = elements * dtype_bytes;
340	
341	    fit::TransferOp transfer_op = fit::TransferOp::TLoad;
342	    switch (input.op) {
343	        case PtoOpcode::TLOAD:
344	            transfer_op = fit::TransferOp::TLoad;
345	            break;
346	        case PtoOpcode::TSTORE:
347	            transfer_op = fit::TransferOp::TStore;
348	            break;
349	        case PtoOpcode::TMOV:
350	            transfer_op = fit::TransferOp::TMov;
351	            break;
352	        default:
353	            return false;
354	    }
355	
356	    long double latency_us = 0.0L;
357	    if (!fit::TryEstimateTransferLatencyUs(
358	            transfer_op, input.tile_type, bytes, predict_config.bandwidth_bytes_per_us, latency_us)) {
359	        return false;
360	    }
361	    result.latency_us = latency_us;
362	    result.cycles = static_cast<double>(latency_us * predict_config.frequency_mhz);
363	    return true;
364	}
365	
366	inline bool TryEstimateA5Cycles(
367	    const CostModelInput& input, const PredictRuntimeConfig& predict_config, CostModelResult& result)
368	{
369	    uint64_t cycles = 0;
370	    if (!a5::TryEstimateA5VfCycles(input, cycles)) {
371	        return WarnAndFallbackToZero(input, result, "unsupported A5 VF curve key");
372	    }
373	    result.cycles = static_cast<double>(cycles);
374	    result.latency_us = evaluator::CyclesToUs(cycles, predict_config.frequency_mhz);
375	    return true;
376	}
377	
378	inline bool TryEstimateTransferCycles(
379	    const CostModelInput& input, const PredictRuntimeConfig& predict_config, CostModelResult& result)
380	{
381	    if (TryEstimateTransferLatency(input, predict_config, result)) {
382	        return true;
383	    }
384	    return WarnAndFallbackToZero(input, result, "unsupported transfer op/tile_type/data_size/dtype");
385	}
386	
387	inline bool TryEstimateMatmulCyclesWithResult(
388	    const CostModelInput& input, const PredictRuntimeConfig& predict_config, CostModelResult& result)
389	{
390	    uint64_t cycles = 0;
391	    if (!TryEstimateMatmulCycles(input, cycles)) {
392	        return WarnAndFallbackToZero(input, result, "unsupported matmul shape/dtype combination");
393	    }
394	    result.cycles = static_cast<double>(cycles);
395	    result.latency_us = evaluator::CyclesToUs(cycles, predict_config.frequency_mhz);
396	    return true;
397	}
398	
399	inline bool TryEstimateElementwiseCycles(
400	    const CostModelInput& input, const PredictRuntimeConfig& predict_config, CostModelResult& result)
401	{
402	    if (input.rows <= 0 || input.cols <= 0) {
403	        return WarnAndFallbackToZero(input, result, "unsupported rows/cols");
404	    }
405	
406	    const uint64_t rows = static_cast<uint64_t>(input.rows);
407	    const uint64_t cols = static_cast<uint64_t>(input.cols);
408	    uint64_t cycles = 0;
409	    bool estimated = false;
410	    switch (input.dtype) {
411	        case DType::Float:
412	            estimated = TryEstimateSupportedCycles<float>(input.op, rows, cols, cycles);
413	            break;
414	        case DType::Half:
415	            estimated = TryEstimateSupportedCycles<half>(input.op, rows, cols, cycles);
416	            break;
417	        default:
418	            return WarnAndFallbackToZero(input, result, "unsupported dtype");
419	    }
420	    if (!estimated) {
421	        return WarnAndFallbackToZero(input, result, "unsupported op/cols parameter combination");
422	    }
423	    (void)predict_config.bandwidth_bytes_per_us;
424	    result.cycles = static_cast<double>(cycles);
425	    result.latency_us = evaluator::CyclesToUs(cycles, predict_config.frequency_mhz);
426	    return true;
427	}
428	
429	inline bool EstimateCycles(
430	    const CostModelInput& input, const PredictRuntimeConfig& predict_config, CostModelResult& result)
431	{
432	    if (input.arch == CostModelArch::A5) {
433	        return TryEstimateA5Cycles(input, predict_config, result);
434	    }
435	    if (input.op == PtoOpcode::TLOAD || input.op == PtoOpcode::TSTORE || input.op == PtoOpcode::TMOV) {
436	        return TryEstimateTransferCycles(input, predict_config, result);
437	    }
438	    if (input.op == PtoOpcode::TMATMUL) {
439	        return TryEstimateMatmulCyclesWithResult(input, predict_config, result);
440	    }
441	    return TryEstimateElementwiseCycles(input, predict_config, result);
442	}
443	
444	inline bool EstimateCycles(const CostModelInput& input, CostModelResult& result)
445	{
446	    const PredictRuntimeConfig default_config = GetDefaultPredictRuntimeConfig();
447	    return EstimateCycles(input, default_config, result);
448	}
449	
450	inline CostModelResult EstimateCycles(const CostModelInput& input)
451	{
452	    CostModelResult result{};
453	    (void)EstimateCycles(input, result);
454	    return result;
455	}
456	
457	} // namespace pto::mocker::lightweight
