12	#define PTO_PERF_SIM_LATENCY_HPP
13	
14	#include "recorder.hpp"
15	#include <pto/common/type.hpp>
16	#include <algorithm>
17	#include <cstdint>
18	#include <initializer_list>
19	#include <string>
20	#include <tuple>
21	#include <type_traits>
22	
23	namespace pto::perf_sim {
24	
25	// ── Compile-time TileType extraction (returns Ctrl for non-tiles) ──
26	
27	template <typename T>
28	constexpr pto::TileType SafeGetTileLoc()
29	{
30	    if constexpr (requires { T::Loc; })
31	        return T::Loc;
32	    else
33	        return pto::TileType::Ctrl;
34	}
35	
36	inline bool IsOneOf(const std::string& opcode, std::initializer_list<const char*> names)
37	{
38	    return std::any_of(names.begin(), names.end(), [&](const char* name) { return opcode == name; });
39	}
40	
41	// ── Static opcode → PipeStage lookup (for non-polymorphic instructions) ──
42	
43	inline PipeStage StaticPipeStageLookup(const std::string& opcode)
44	{
45	    if (IsOneOf(
46	            opcode, {"TSYNC", "TRESHAPE", "TASSIGN", "TPRINT", "TGET_SCALE_ADDR", "TSUBVIEW", "TALLOC", "TFREE",
47	                     "TPUSH", "TPOP"})) {
48	        return PipeStage::Scalar;
49	    }
50	    if (IsOneOf(opcode, {"TMATMUL", "TMATMUL_ACC", "TMATMUL_BIAS", "TGEMV", "TGEMV_ACC", "TGEMV_BIAS"})) {
51	        return PipeStage::Matrix;
52	    }
53	    if (opcode == "TIMG2COL" || opcode == "TTRANS") {
54	        return PipeStage::MTE1;
55	    }
56	    if (opcode == "TLOAD" || opcode == "TPREFETCH") {
57	        return PipeStage::MTE2_AIV;
58	    }
59	    if (opcode == "TSTORE") {
60	        return PipeStage::MTE3;
61	    }
62	    return PipeStage::Vector;
63	}
64	
65	inline PipeStage ResolveOnChipMoveStage(pto::TileType dst_loc, pto::TileType src_loc)
66	{
67	    if (src_loc == pto::TileType::Acc) {
68	        return PipeStage::Fixpipe;
69	    }
70	    if (dst_loc == pto::TileType::Vec) {
71	        return src_loc == pto::TileType::Mat ? PipeStage::MTE1 : PipeStage::Vector;
72	    }
73	    return src_loc == pto::TileType::Vec ? PipeStage::MTE3 : PipeStage::MTE1;
74	}
75	
76	// ── Dynamic resolution: opcode + TileTypes → PipeStage ──
77	
78	inline PipeStage ResolvePipeStage(const std::string& opcode, pto::TileType dst_loc, pto::TileType src_loc)
79	{
80	    // TLOAD: GM/L2 → tile. dst tile determines MTE2_AIV (→UB) or MTE2_AIC (→L1)
81	    if (opcode == "TLOAD") {
82	        return (dst_loc == pto::TileType::Vec) ? PipeStage::MTE2_AIV : PipeStage::MTE2_AIC;
83	    }
84	    // TPREFETCH: always GM→UB (AIV side)
85	    if (opcode == "TPREFETCH") {
86	        return PipeStage::MTE2_AIV;
87	    }
88	    // TSTORE: tile → GM/L2. src tile determines component:
89	    //   Vec(UB)→GM: MTE3, Mat(L1)→GM: MTE3, Acc(L0C)→GM: Fixpipe
90	    if (opcode == "TSTORE") {
91	        if (src_loc == pto::TileType::Acc)
92	            return PipeStage::Fixpipe;
93	        return PipeStage::MTE3;
94	    }
95	    // TMOV: on-chip transfer, routing depends on dst+src buffer types
96	    //   dst=Vec(UB): src=Vec→Vector, src=Mat(L1)→MTE1, src=Acc(L0C)→Fixpipe
97	    //   dst=Mat(L1): src=Acc(L0C)→Fixpipe, src=Mat→MTE1, src=Vec(UB)→MTE3
98	    if (opcode == "TMOV") {
99	        return ResolveOnChipMoveStage(dst_loc, src_loc);
100	    }
101	    // TEXTRACT: sub-tile extract, same routing as TMOV (data movement
102	    // depends on src/dst buffer types)
103	    //   e.g. L1→L0A/L0B = MTE1, L0C→UB = Fixpipe, UB→UB = Vector
104	    if (opcode == "TEXTRACT") {
105	        return ResolveOnChipMoveStage(dst_loc, src_loc);
106	    }
107	    // TTRANS: L1→L1 transpose → MTE1
108	    if (opcode == "TTRANS")
109	        return PipeStage::MTE1;
110	
111	    return StaticPipeStageLookup(opcode);
112	}
113	
114	// ── Variadic dispatch: extract TileTypes from macro arguments ──
115	
116	inline PipeStage ResolvePipeStageArgs(const char* opcode)
117	{
118	    return ResolvePipeStage(opcode, pto::TileType::Ctrl, pto::TileType::Ctrl);
119	}
120	
121	template <typename First, typename... Rest>
122	inline PipeStage ResolvePipeStageArgs(const char* opcode, First&, const Rest&...)
123	{
124	    using DstType = std::remove_cv_t<std::remove_reference_t<First>>;
125	    constexpr auto dst_loc = SafeGetTileLoc<DstType>();
126	    if constexpr (sizeof...(Rest) > 0) {
127	        using SrcType = std::remove_cv_t<std::remove_reference_t<std::tuple_element_t<0, std::tuple<Rest...>>>>;
128	        constexpr auto src_loc = SafeGetTileLoc<SrcType>();
129	        return ResolvePipeStage(opcode, dst_loc, src_loc);
130	    } else {
131	        return ResolvePipeStage(opcode, dst_loc, pto::TileType::Ctrl);
132	    }
133	}
134	
135	// ── Instructions that need CPU simulation (iterative convergence depends on values) ──
136	
137	inline bool NeedsCpuSim(const std::string& opcode)
138	{
139	    static const std::unordered_map<std::string, bool> lut = {
140	        {"TEXP", true}, {"TLOG", true}, {"TSQRT", true}, {"TRSQRT", true}, {"TDIV", true}, {"TDIVS", true},
141	    };
142	    auto it = lut.find(opcode);
143	    return it != lut.end() ? it->second : false;
144	}
145	
146	// ── Backward-compatible alias ──
147	inline PipeStage OpToPipeStage(const std::string& opcode) __attribute__((deprecated));
148	inline PipeStage OpToPipeStage(const std::string& opcode) { return StaticPipeStageLookup(opcode); }
149	
150	} // namespace pto::perf_sim
151	
152	#endif
