10	
11	#ifndef PTO_PERF_SIM_RECORDER_HPP
12	#define PTO_PERF_SIM_RECORDER_HPP
13	
14	#include <cstdint>
15	#include <string>
16	#include <string_view>
17	#include <vector>
18	
19	namespace pto::perf_sim {
20	
21	// Thread-local subblock ID, set by LAUNCH_KERNEL before kernel execution.
22	// Used by PtoRecorder/SyncRecorder to filter Cube vs Vec instructions.
23	inline thread_local uint32_t current_subblock_id = 0;
24	
25	using event_t = int;
26	
27	enum class CvSyncKind : uint8_t {
28	    None,
29	    Push,
30	    Pop,
31	    Free,
32	    Alloc,
33	};
34	
35	// ── PipeStage: NPU pipeline stages ──
36	
37	enum class PipeStage : uint8_t {
38	    Scalar,
39	    MTE2_AIV, // GM/L2 → UB
40	    MTE2_AIC, // GM/L2 → L1
41	    MTE3,     // L1 → GM, UB → GM, UB → L1
42	    MTE1,     // L1 → L0A, L1 → L0B, L1 → UB, L1 → L1, L1 → BT/FB
43	    Vector,   // VEC compute + UB → UB
44	    Fixpipe,  // L0C → GM, L0C → L1, L0C → UB
45	    Matrix,   // CUBE (TMATMUL, TGEMV)
46	    COUNT,
47	};
48	
49	constexpr const char* PipeStageName(PipeStage s)
50	{
51	    constexpr const char* names[] = {"Scalar", "MTE2_AIV", "MTE2_AIC", "MTE3", "MTE1", "VEC", "FIXP", "CUBE"};
52	    return names[static_cast<int>(s)];
53	}
54	
55	inline bool IsGMAccessPipe(PipeStage s)
56	{
57	    return s == PipeStage::MTE2_AIV || s == PipeStage::MTE2_AIC || s == PipeStage::MTE3 || s == PipeStage::Fixpipe;
58	}
59	
60	inline bool IsAICStage(PipeStage s)
61	{
62	    return s == PipeStage::MTE2_AIC || s == PipeStage::MTE1 || s == PipeStage::Matrix || s == PipeStage::Fixpipe;
63	}
64	
65	inline bool IsAIVStage(PipeStage s)
66	{
67	    return s == PipeStage::MTE2_AIV || s == PipeStage::Vector || s == PipeStage::MTE3;
68	}
69	
70	// IsCubeSidePipe: hardware pipe IDs belonging to CubeCore (AIC)
71	inline bool IsCubeSidePipe(int hw_pipe) { return hw_pipe == PIPE_MTE1 || hw_pipe == PIPE_M || hw_pipe == PIPE_FIX; }
72	
73	// ── PTO instruction record ──
74	
75	struct InstrRecord {
76	    std::string opcode;    // "TLOAD", "TADD", ...
77	    std::string dtype;     // "fp16", "fp32", "int8", ...
78	    std::string tile_args; // stringified tile arguments, e.g. "ub_out, ub_a, ub_b"
79	    int rows = 0;
80	    int cols = 0;
81	    uint64_t estimated_cycles = 0;
82	    PipeStage stage = PipeStage::Vector;
83	    static constexpr int MAX_WAIT_EVENTS = 8;
84	    event_t signal_event = -1;
85	    event_t wait_events[MAX_WAIT_EVENTS] = {-1, -1, -1, -1, -1, -1, -1, -1};
86	    int wait_count = 0;
87	    static constexpr int MAX_SYNC_SIGNALS = 8;
88	    event_t extra_sync_signals[MAX_SYNC_SIGNALS] = {-1, -1, -1, -1, -1, -1, -1, -1};
89	    int extra_sync_signal_count = 0;
90	    uint64_t seq = 0;         // global sequence number for merge ordering
91	    uint32_t core_id = 0;     // recording core
92	    uint32_t subblock_id = 0; // VecCore index (0 or 1)
93	    CvSyncKind cv_kind = CvSyncKind::None;
94	    uint64_t cv_key = 0; // logical FIFO identity for TPUSH/TPOP token matching
95	};
96	
97	enum class SyncKind : uint8_t { Signal, Wait, Barrier };
98	
99	struct SyncRecord {
100	    SyncKind kind;
101	    event_t event_id = -1;
102	    int src_pipe = -1;
103	    int dst_pipe = -1;
104	    bool cross_core = false;
105	    uint64_t seq = 0;         // global sequence number for merge ordering
106	    uint32_t core_id = 0;     // recording core
107	    uint32_t subblock_id = 0; // VecCore index (0 or 1)
108	};
109	
110	// ── Shared global sequence counter (preserves ordering across recorders) ──
111	
112	inline uint64_t SharedNextSeq()
113	{
114	    static thread_local uint64_t counter = 0;
115	    return counter++;
116	}
117	
118	template <typename Record>
119	class CoreRecordStorage {
120	public:
121	    static std::vector<std::vector<Record>>& AllCoreRecords()
122	    {
123	        static thread_local std::vector<std::vector<Record>> per_core;
124	        return per_core;
125	    }
126	
127	    static std::vector<Record>& GetForCore(uint32_t core_id)
128	    {
129	        auto& all = AllCoreRecords();
130	        if (core_id >= all.size())
131	            all.resize(core_id + 1);
132	        return all[core_id];
133	    }
134	
135	    static std::vector<Record>& Get() { return GetForCore(ActiveCore()); }
136	
137	    static void SetActiveCore(uint32_t id)
138	    {
139	        ActiveCoreRef() = id;
140	        GetForCore(id);
141	    }
142	
143	    static uint32_t ActiveCore() { return ActiveCoreRef(); }
144	
145	    static void Clear()
146	    {
147	        AllCoreRecords().clear();
148	        AllCoreRecords().resize(1);
149	    }
150	
151	private:
152	    static uint32_t& ActiveCoreRef()
153	    {
154	        static thread_local uint32_t id = 0;
155	        return id;
156	    }
157	};
158	
159	// ── PTO instruction recorder (per-core, thread-local) ──
160	
161	class PtoRecorder : public CoreRecordStorage<InstrRecord> {
162	public:
163	    static void Record(InstrRecord r)
164	    {
165	        auto sub_id = current_subblock_id;
166	        if (sub_id > 0 && (IsAICStage(r.stage) || r.stage == PipeStage::Scalar))
167	            return;
168	        r.subblock_id = sub_id;
169	        r.core_id = ActiveCore();
170	        r.seq = NextSeq();
171	        Get().push_back(std::move(r));
172	    }
173	    static size_t Size() { return Get().size(); }
174	
175	private:
176	    static uint64_t NextSeq() { return SharedNextSeq(); }
177	};
178	
179	// ── Sync event recorder (per-core, thread-local) ──
180	
181	class SyncRecorder : public CoreRecordStorage<SyncRecord> {
182	public:
183	    static void Signal(event_t id, int src, int dst, bool cross = false)
184	    {
185	        auto sub_id = current_subblock_id;
186	        if (sub_id > 0) {
187	            // Skip Cube-side signals (already recorded by subblock_id=0)
188	            if (IsCubeSidePipe(src))
189	                return;
190	            // PIPE_MTE2(3) with Cube dst is MTE2_AIC → skip
191	            if (src == PIPE_MTE2 && IsCubeSidePipe(dst))
192	                return;
193	        }
194	        Get().push_back({SyncKind::Signal, id, src, dst, cross, NextSeq(), ActiveCore(), sub_id});
195	    }
196	    static void Wait(event_t id, int src, int dst, bool cross = false)
197	    {
198	        auto sub_id = current_subblock_id;
199	        if (sub_id > 0) {
200	            // Skip Cube-side waits (already recorded by subblock_id=0)
201	            if (IsCubeSidePipe(dst))
202	                return;
203	        }
204	        Get().push_back({SyncKind::Wait, id, src, dst, cross, NextSeq(), ActiveCore(), sub_id});
205	    }
206	    static void Barrier(int pipe)
207	    {
208	        Get().push_back({SyncKind::Barrier, -1, pipe, -1, false, NextSeq(), ActiveCore()});
209	    }
210	
211	private:
212	    static uint64_t NextSeq() { return SharedNextSeq(); }
213	};
214	
215	// ── CV FIFO metadata recorder ──
216	// TPUSH/TPOP are scalar instructions in perf-sim, but they define the ordering
217	// between FIFO data producers and consumers. Attach a compact logical FIFO key
218	// to the next recorded TPUSH/TPOP instruction, then let pipe_model build the
219	// ready-token dependencies in merged instruction order.
220	
221	class CvSyncRecorder {
222	public:
223	    struct PendingMeta {
224	        CvSyncKind kind = CvSyncKind::None;
225	        uint64_t key = 0;
226	    };
227	
228	    static void SetPending(CvSyncKind kind, uint64_t key) { Pending() = {kind, key}; }
229	
230	    static void ApplyPending(const char* opcode, InstrRecord& record)
231	    {
232	        auto& pending = Pending();
233	        if (pending.kind == CvSyncKind::None)
234	            return;
235	        std::string_view op(opcode);
236	        bool matches = (pending.kind == CvSyncKind::Push && op == "TPUSH") ||
237	                       (pending.kind == CvSyncKind::Pop && op == "TPOP") ||
238	                       (pending.kind == CvSyncKind::Free && op == "TFREE") ||
239	                       (pending.kind == CvSyncKind::Alloc && op == "TALLOC");
240	        if (matches) {
241	            record.cv_kind = pending.kind;
242	            record.cv_key = pending.key;
243	        }
244	        pending = {};
245	    }
246	
247	    static void Clear() { Pending() = {}; }
248	
249	private:
250	    static PendingMeta& Pending()
251	    {
252	        static thread_local PendingMeta pending;
253	        return pending;
254	    }
255	};
256	
257	// Direction encoding for TPipe (matches Direction::DIR_* in fifo.hpp)
258	enum class TPipeDir : uint8_t {
259	    DIR_C2V = 1,  // Cube → Vec
260	    DIR_V2C = 2,  // Vec → Cube
261	    DIR_BOTH = 3, // Both directions
262	    DIR_V2C_CTRL = 4
263	};
264	
265	inline uint8_t CvKeyDirection(uint64_t key)
266	{
267	    constexpr uint8_t DIR_TYPE_MASK = 0xffu;
268	    constexpr int DIR_TYPE_SHIFT = 8;
269	    return static_cast<uint8_t>((key >> DIR_TYPE_SHIFT) & DIR_TYPE_MASK);
270	}
271	
272	inline uint64_t NextCvFifoTypeId()
273	{
274	    static thread_local uint64_t next_id = 1;
275	    return next_id++;
276	}
277	
278	template <typename Pipe>
279	uint64_t CvFifoTypeId()
280	{
281	    static const uint64_t id = NextCvFifoTypeId();
282	    return id;
283	}
284	
285	template <typename Pipe>
