11	inline void SignalChannel(std::vector<EventChannel> &channels, event_t event, uint64_t now)
12	{
13	    if (event < 0 || static_cast<size_t>(event) >= channels.size())
14	        return;
15	    auto &channel = channels[event];
16	    channel.count++;
17	    channel.signal_cycle = now;
18	}
19	
20	inline bool AnyRunning(const std::vector<PipeQueue> &queues)
21	{
22	    for (auto &q : queues) {
23	        if (q.current && q.current->state == PipeEntry::RUNNING)
24	            return true;
25	    }
26	    return false;
27	}
28	
29	struct StepProgress {
30	    bool any_active = false;
31	    bool dispatched = false;
32	    uint64_t next_event = UINT64_MAX;
33	};
34	
35	template <typename SignalFn>
36	inline void CompleteRunningEntryCommon(PipeQueue &queue, PipeTimeline &timeline, uint64_t now, StepProgress &progress,
37	                                       SignalFn signal_fn)
38	{
39	    if (!queue.current || queue.current->state != PipeEntry::RUNNING)
40	        return;
41	    progress.any_active = true;
42	    if (now < queue.current->end_cycle) {
43	        progress.next_event = std::min(progress.next_event, queue.current->end_cycle);
44	        return;
45	    }
46	    timeline.events.push_back(BuildPipeEvent(*queue.current, queue.label));
47	    signal_fn(queue.current->signal_event);
48	    for (int si = 0; si < queue.current->extra_signal_count; ++si)
49	        signal_fn(queue.current->extra_signals[si]);
50	    queue.current->state = PipeEntry::DONE;
51	    queue.current = nullptr;
52	    queue.next_free_cycle = now;
53	}
54	
55	inline void CompleteRunningEntry(PipeQueue &queue, PipeTimeline &timeline, std::vector<EventChannel> &channels,
56	                                 uint64_t now, StepProgress &progress)
57	{
58	    CompleteRunningEntryCommon(queue, timeline, now, progress,
59	                               [&](event_t event) { SignalChannel(channels, event, now); });
60	}
61	
62	inline void PopDoneEntries(std::vector<PipeQueue> &queues)
63	{
64	    for (auto &queue : queues) {
65	        while (!queue.entries.empty() && queue.entries.front().state == PipeEntry::DONE)
66	            queue.entries.pop_front();
67	    }
68	}
69	
70	inline bool SingleCoreWaitsReady(const PipeEntry &entry, const std::vector<EventChannel> &channels)
71	{
72	    for (int i = 0; i < entry.wait_count; ++i) {
73	        event_t wait = entry.wait_events[i];
74	        if (wait >= 0 && (static_cast<size_t>(wait) >= channels.size() || !channels[wait].signaled()))
75	            return false;
76	    }
77	    return true;
78	}
79	
80	inline void ConsumeSingleCoreSyncWaits(const PipeEntry &entry, std::vector<EventChannel> &channels)
81	{
82	    int sync_base = SyncChannelBase();
83	    for (int i = 0; i < entry.wait_count; ++i) {
84	        event_t wait = entry.wait_events[i];
85	        if (wait >= sync_base && static_cast<size_t>(wait) < channels.size())
86	            channels[wait].count--;
87	    }
88	}
