105	inline void TryDispatchSingleCore(PipeQueue &queue, std::vector<EventChannel> &channels, L2CacheModel &cache,
106	                                  uint64_t now, StepProgress &progress)
107	{
108	    if (!queue.CanAccept() || queue.entries.empty())
109	        return;
110	    auto &entry = queue.entries.front();
111	    if (entry.name == "BARRIER") {
112	        StartEntry(queue, entry, now, cache, progress);
113	        return;
114	    }
115	    if (entry.wait_count > 0 && entry.state == PipeEntry::WAITING) {
116	        if (!SingleCoreWaitsReady(entry, channels)) {
117	            progress.any_active = true;
118	            return;
119	        }
120	        ConsumeSingleCoreSyncWaits(entry, channels);
121	        entry.state = PipeEntry::IDLE;
122	    }
123	    if (entry.state == PipeEntry::IDLE)
124	        StartEntry(queue, entry, now, cache, progress);
125	}
