282	    auto queues = MakePipeQueues();
283	    std::vector<EventChannel> channels(TotalChannels());
284	    FillQueuesFromMerged(queues, channels, merged);
285	
286	    L2CacheModel cache;
287	    return StepSimulate(queues, channels, cache);
288	}
