357	inline void ConsumeMultiCoreSyncWaits(const PipeEntry &entry, uint32_t core_id,
358	                                      std::vector<EventChannel> &intra_channels,
359	                                      std::vector<EventChannel> &cross_channels)
360	{
361	    int sync_base = SyncChannelBase();
362	    for (int i = 0; i < entry.wait_count; ++i) {
363	        if (entry.wait_events[i] < sync_base)
364	            continue;
365	        auto *channel = LookupChannel(intra_channels, cross_channels, core_id, entry.wait_events[i]);
366	        if (channel)
