423	// ── Event-driven multi-core step simulation ──
424	
425	inline MultiCoreTimeline StepSimulateMultiCore(std::vector<CorePipeline> &core_pipelines,
426	                                               std::vector<EventChannel> &intra_channels,
427	                                               std::vector<EventChannel> &cross_channels, L2CacheModel &cache,
428	                                               uint32_t max_steps = 500000)
429	{
430	    MultiCoreTimeline result;
431	    result.per_core.resize(core_pipelines.size());
432	    uint64_t now = 0;
433	
434	    for (uint32_t step = 0; step < max_steps; ++step) {
435	        StepProgress progress;
436	        for (auto &cp : core_pipelines) {
437	            for (auto &queue : cp.queues)
438	                CompleteRunningEntry(cp, queue, result.per_core[cp.core_id], intra_channels, cross_channels, now,
439	                                     progress);
440	        }
441	
442	        for (auto &cp : core_pipelines)
443	            PopDoneEntries(cp.queues);
444	
445	        for (auto &cp : core_pipelines) {
446	            for (auto &queue : cp.queues)
447	                TryDispatchMultiCore(cp, queue, intra_channels, cross_channels, cache, now, progress);
448	        }
449	
450	        if (!progress.any_active)
451	            break;
452	        if (!progress.dispatched) {
453	            if (!AnyRunning(core_pipelines))
454	                break; // true deadlock
455	        }
456	        if (progress.next_event != UINT64_MAX && progress.next_event > now)
457	            now = progress.next_event;
458	    }
459	
460	    CollectStuckEntries(core_pipelines, result);
461	
462	    for (auto &tl : result.per_core) {
463	        for (auto &ev : tl.events)
464	            tl.total_cycles = std::max(tl.total_cycles, ev.end_cycle);
465	        result.total_cycles = std::max(result.total_cycles, tl.total_cycles);
466	    }
467	    return result;
468	}
