97	inline bool TryGetA5ElementsPerRepeatByDTypeKey(std::string_view dtype_key, uint64_t& elements_per_repeat)
98	{
99	    if (dtype_key == "fp4_e1m2" || dtype_key == "fp4_e2m1") {
100	        elements_per_repeat = kElementsPerRepeatB8;
101	        return true;
102	    }
103	    if (dtype_key == "fp16" || dtype_key == "bf16") {
104	        elements_per_repeat = kElementsPerRepeatB16;
105	        return true;
106	    }
107	    if (dtype_key == "fp32" || dtype_key == "int32" || dtype_key == "uint32" || dtype_key == "fp8_e4m3" ||
108	        dtype_key == "fp8_e5m2" || dtype_key == "hif8") {
109	        elements_per_repeat = kElementsPerRepeatB32;
110	        return true;
111	    }
112	    if (dtype_key == "int8" || dtype_key == "uint8") {
113	        elements_per_repeat = kElementsPerRepeatB8;
114	        return true;
115	    }
116	    if (dtype_key == "int16" || dtype_key == "uint16") {
117	        elements_per_repeat = kElementsPerRepeatB16;
118	        return true;
119	    }
120	    return false;
121	}
