135	    if (shape_path == fit::ShapePath::Path1D) {
136	        return TryGetA5ElementsPerRepeatByDTypeKey(src_dtype, elements_per_repeat);
137	    }
138	    if ((src_dtype == "fp32" && (dst_dtype == "fp16" || dst_dtype == "bf16" || dst_dtype == "fp8_e4m3" ||
139	                                 dst_dtype == "fp8_e5m2" || dst_dtype == "hif8")) ||
140	        ((src_dtype == "fp16" || src_dtype == "bf16") &&
141	         (dst_dtype == "fp16" || dst_dtype == "fp4_e1m2" || dst_dtype == "fp4_e2m1" || dst_dtype == "hif8"))) {
142	        elements_per_repeat = kElementsPerRepeatB16;
143	        return true;
144	    }
