225	{
226	    switch (vf_impl_kind) {
227	        case VFImplKind::VFIMPL_1D_NO_POST_UPDATE:
228	            return "NO_POST_UPDATE";
229	        case VFImplKind::VFIMPL_2D_NO_POST_UPDATE:
230	            return "NO_POST_UPDATE";
231	        case VFImplKind::VFIMPL_1D_POST_UPDATE:
232	            return "POST_UPDATE";
233	        case VFImplKind::VFIMPL_2D_POST_UPDATE:
234	            return "POST_UPDATE";
235	        case VFImplKind::VFIMPL_DEFAULT:
236	        default:
237	            return ResolveDefaultVfImplKind(op, shape_path);
238	    }
239	}
240	
241	struct VfCurveContext {
242	    int64_t valid_rows_i = 0;
243	    int64_t valid_cols_i = 0;
244	    std::string_view op_key;
245	    fit::ShapePath shape_path = fit::ShapePath::Path1D;
246	    std::string_view src_dtype;
247	    std::string_view dst_dtype = "none";
248	    std::string_view op_params;
249	    uint64_t elements_per_repeat = 0;
250	};
251	
252	inline bool TryInitVfCurveContext(const CostModelInput& input, VfCurveContext& context)
253	{
254	    context.valid_rows_i = input.valid_rows > 0 ? input.valid_rows : input.rows;
255	    context.valid_cols_i = input.valid_cols > 0 ? input.valid_cols : input.cols;
256	    if (context.valid_rows_i <= 0 || context.valid_cols_i <= 0) {
257	        return false;
258	    }
259	
260	    context.op_key = PtoOpcodeToKey(input.op);
261	    if (context.op_key.empty()) {
262	        return false;
263	    }
264	    context.shape_path = ResolveShapePath(input.op, input.rows, input.cols, context.valid_cols_i);
265	    context.src_dtype = DTypeToKey(input.dtype);
266	    context.op_params = input.a5_op_params;
267	    return !context.src_dtype.empty();
268	}
269	
270	inline bool TryResolveVfOpParams(const CostModelInput& input, VfCurveContext& context)
271	{
272	    if (input.op == PtoOpcode::TCVT) {
273	        context.dst_dtype = DTypeToKey(input.dst_dtype);
274	        if (context.op_params.empty()) {
275	            context.op_params =
276	                (input.round_mode == RoundMode::CAST_NONE && input.saturation_mode == SaturationMode::ON) ?
277	                    std::string_view("CAST_RINT_SAT_ON_normal") :
278	                    CvtOpParams(input.round_mode, input.saturation_mode);
279	        }
280	    } else if (context.op_params.empty()) {
281	        context.op_params = DefaultOpParams(input.op);
282	    }
283	    return !context.dst_dtype.empty();
284	}
285	
286	inline bool TryResolveElementsPerRepeat(const CostModelInput& input, VfCurveContext& context)
287	{
288	    if (input.op == PtoOpcode::TCVT) {
289	        return TryGetA5CvtElementsPerRepeat(
290	            context.src_dtype, context.dst_dtype, context.shape_path, context.elements_per_repeat);
291	    }
292	    return TryGetA5ElementsPerRepeat(input.dtype, context.elements_per_repeat);
293	}
294	
295	inline void ResolveLoopCounts(
296	    const VfCurveContext& context, uint64_t& loop_count, uint64_t& outer_iter, uint64_t& inner_iter,
297	    uint64_t& tail_count)
298	{
299	    const uint64_t valid_rows = static_cast<uint64_t>(context.valid_rows_i);
300	    const uint64_t valid_cols = static_cast<uint64_t>(context.valid_cols_i);
301	    if (context.shape_path == fit::ShapePath::Path1D) {
302	        inner_iter = CeilDivU64(valid_rows * valid_cols, context.elements_per_repeat);
303	        outer_iter = 1;
304	        loop_count = inner_iter;
305	        tail_count = (valid_rows * valid_cols) % context.elements_per_repeat;
306	        return;
307	    }
308	    inner_iter = CeilDivU64(valid_cols, context.elements_per_repeat);
309	    outer_iter = valid_rows;
310	    loop_count = outer_iter * inner_iter;
311	    tail_count = valid_cols % context.elements_per_repeat;
312	}
313	
314	inline bool TryResolveTselOpParams(const CostModelInput& input, uint64_t inner_iter, VfCurveContext& context)
315	{
316	    if (input.op != PtoOpcode::TSEL) {
317	        return true;
318	    }
319	    if (context.op_params.empty()) {
320	        context.op_params = TselOpParams(input.dtype, context.shape_path, inner_iter);
321	    }
322	    return !context.op_params.empty();
323	}
324	
325	inline bool BuildVfCurveKeyAndLoopCount(
326	    const CostModelInput& input, fit::VfCurveKey& key, uint64_t& loop_count, uint64_t& outer_iter, uint64_t& inner_iter,
327	    uint64_t& tail_count)
328	{
329	    VfCurveContext context;
330	    if (!TryInitVfCurveContext(input, context) || !TryResolveVfOpParams(input, context) ||
331	        !TryResolveElementsPerRepeat(input, context) || context.elements_per_repeat == 0) {
332	        return false;
333	    }
334	
335	    ResolveLoopCounts(context, loop_count, outer_iter, inner_iter, tail_count);
336	    const auto tail_kind = tail_count == 0 ? fit::TailKind::Full : fit::TailKind::Tail;
337	    if (!TryResolveTselOpParams(input, inner_iter, context)) {
338	        return false;
339	    }
340	
341	    key = fit::VfCurveKey{
342	        context.op_key,
343	        context.src_dtype,
344	        context.dst_dtype,
345	        context.shape_path,
346	        ResolveVfImplKind(input.op, input.vf_impl_kind, context.shape_path),
347	        tail_kind,
348	        context.op_params,
349	    };
350	    return true;
351	}
352	
353	inline bool TryEstimateA5VfCycles(const CostModelInput& input, uint64_t& cycles)
354	{
355	    fit::VfCurveKey key{};
356	    uint64_t loop_count = 0;
357	    uint64_t outer_iter = 0;
358	    uint64_t inner_iter = 0;
359	    uint64_t tail_count = 0;
360	    if (!BuildVfCurveKeyAndLoopCount(input, key, loop_count, outer_iter, inner_iter, tail_count)) {
361	        return false;
362	    }
363	
364	    const fit::VfFormulaParam* param = nullptr;
365	    if (!fit::TryLookupVfFormulaParam(key, param)) {
366	        return false;
367	    }
368	
369	    cycles = fit::EvalVfFormula(*param, loop_count, outer_iter, inner_iter, tail_count);
370	    return true;
371	}
372	
373	} // namespace pto::mocker::lightweight::a5
374	
375	#endif
